namespace ghidra.feature.vt.gui.actions;





using docking;
using docking.action;
using generic.theme;
using ghidra.feature.vt.api.main;
using ghidra.feature.vt.api.main;
using ghidra.feature.vt.gui.plugin;
using ghidra.feature.vt.gui.plugin;
using ghidra.feature.vt.gui.provider.matchtable;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.util;

public class CreateSelectionAction : DockingAction {
	public static readonly string NAME = "Create Match Table Selection";
	private static readonly string MENU_GROUP = "Selection";
	private static readonly Icon ICON = new GIcon("icon.version.tracking.action.create.selection");
	private VTController controller;

	public CreateSelectionAction(VTController controller) : base(NAME, VTPlugin.OWNER)
    {
		this.controller = controller;
		setToolBarData(new ToolBarData(ICON, MENU_GROUP));
		setPopupMenuData(new MenuData(new string[] { "Make Selections" }, ICON, MENU_GROUP));
		setEnabled(false);
		setHelpLocation(new HelpLocation("VersionTrackingPlugin", "Make Selections"));
		setDescription(
			"Makes selections in both the source and destination tools for the selected matches.");
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		if (!(context is VTMatchContext)) {
			return false;
		}
		VTMatchContext matchContext = (VTMatchContext) context;
		List<VTMatch> matches = matchContext.getSelectedMatches();
		if (matches.size() == 0) {
			return false;
		}
		return true;
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		Program sourceProgram = controller.getSourceProgram();
		Program destinationProgram = controller.getDestinationProgram();
		AddressSet sourceSet = new AddressSet();
		AddressSet destinationSet = new AddressSet();
		VTMatchContext matchContext = (VTMatchContext) context;
		List<VTMatch> matches = matchContext.getSelectedMatches();
		foreach (VTMatch vtMatch in matches) {
			VTAssociation association = vtMatch.getAssociation();
			sourceSet.add(association.getSourceAddress());
			destinationSet.add(association.getDestinationAddress());
		}
		controller.setSelectionInSourceTool(sourceSet);
		controller.setSelectionInDestinationTool(destinationSet);
	}

}
